def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    people_patches = image_patch.find("person")

    if not people_patches:
        return image_patch

    target_person = None
    max_score = -1

    for person in people_patches:
        score = 0

        # Check for green and white shirt
        shirt_patches = person.find("shirt")
        for shirt in shirt_patches:
            if "green" in shirt.best_text_match(["green", "white"]) and "white" in shirt.best_text_match(["green", "white"]):
                score += 1

        # Check for red necktie
        necktie_patches = person.find("necktie")
        for necktie in necktie_patches:
            if "red" in necktie.best_text_match(["red"]):
                score += 1

        if score > max_score:
            max_score = score
            target_person = person

    return target_person

